def parse_display_number(raw):
    """Convert a DISPLAY numeric field like GnuCOBOL's libcob.

    Leading bytes whose low nibble is zero are skipped, then the value is
    accumulated as an unsigned 64-bit integer using (byte - '0') for each
    remaining position.
    """
    size = len(raw)
    if size and raw[0] == 0xFF:
        return 10 ** size
    if size and raw[0] == 0x00:
        return -(10 ** size)

    start = 0
    while size - start > 1 and (raw[start] & 0x0F) == 0:
        start += 1

    value = 0
    for byte in raw[start:]:
        value = (value * 10 + (byte - 0x30)) & 0xFFFFFFFFFFFFFFFF
    return value

